<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Request;use App\Core\Response;use App\Core\Session;use App\Core\View;use App\Models\Catalog;use App\Models\AuditLog;use PDOException;

final class CatalogController
{
 public function domains(Request $r):void{$this->index('domaines',$r);} public function programs(Request $r):void{$this->index('formations',$r);} public function institutions(Request $r):void{$this->index('etablissements',$r);} public function careers(Request $r):void{$this->index('metiers',$r);}
 public function saveDomains(Request $r):void{$this->save('domaines',$r);}public function savePrograms(Request $r):void{$this->save('formations',$r);}public function saveInstitutions(Request $r):void{$this->save('etablissements',$r);}public function saveCareers(Request $r):void{$this->save('metiers',$r);}
 private function index(string $type,Request $r):void{if(!$this->admin())return;$id=filter_var($r->query['edit']??null,FILTER_VALIDATE_INT);$item=$id?Catalog::find($type,(int)$id):null;$values=Session::consumeFlash('values',$item??[]);View::render('admin/catalog',['pageTitle'=>'Référentiel · '.$this->label($type),'currentUser'=>Session::user(),'type'=>$type,'label'=>$this->label($type),'items'=>Catalog::all($type),'item'=>$item,'values'=>$values,'relations'=>$item?Catalog::relations($type,(int)$item['id']):[],'choices'=>Catalog::choices(),'errors'=>Session::consumeFlash('errors',[]),'success'=>Session::consumeFlash('success'),'csrfToken'=>Session::csrfToken()]);}
 private function save(string $type,Request $r):void{if(!$this->admin())return;if(!Session::verifyCsrfToken($r->body['_csrf_token']??null)){Response::text('Session expirée.',403);return;}$actor=Session::user();$id=filter_var($r->body['item_id']??null,FILTER_VALIDATE_INT);$action=(string)($r->body['action']??'');$base=$this->path('/admin/referentiel/'.$type);if(in_array($action,['toggle','delete'],true)){$before=$id?Catalog::find($type,(int)$id):null;if(!$id||!$before){Session::flash('errors',['Entrée introuvable.']);}elseif($action==='toggle'){Catalog::toggle($type,(int)$id);AuditLog::record((int)$actor['id'],'catalog.status_changed',$type,(int)$id,['from'=>(int)$before['is_active'],'to'=>(int)!$before['is_active']],$r->server['REMOTE_ADDR']??null);Session::flash('success','Statut mis à jour.');}else{try{Catalog::delete($type,(int)$id);AuditLog::record((int)$actor['id'],'catalog.deleted',$type,(int)$id,['name'=>$before['name']??null],$r->server['REMOTE_ADDR']??null);Session::flash('success','Entrée supprimée.');}catch(PDOException $e){if($e->getCode()==='23000')Session::flash('errors',['Cette entrée est utilisée par une autre donnée. Désactive-la pour préserver le référentiel et l’historique.']);else throw$e;}}Response::redirect($base);return;}
 if(!in_array($action,['create','update'],true)){Response::text('Action invalide.',400);return;}$fields=match($type){'domaines'=>['name','slug','description','icon_key'],'formations'=>['domain_id','name','slug','description','admission_requirements','duration','degree_level'],'etablissements'=>['name','description','institution_type','address','city','department','website','phone','email'],'metiers'=>['domain_id','name','description','opportunities']};$v=[];foreach($fields as $f)$v[$f]=is_scalar($r->body[$f]??null)?trim((string)$r->body[$f]):'';$v['is_active']=isset($r->body['is_active'])?1:0;$v['name']=trim($v['name']??'');$errors=[];if($v['name']===''||mb_strlen($v['name'])>200)$errors[]='Le nom est obligatoire (200 caractères maximum).';if(in_array($type,['domaines','formations'],true)){$v['slug']=$this->slug($v['slug']?:$v['name']);if(strlen($v['slug'])>220)$errors[]='Le code URL est trop long.';if($v['slug']==='')$errors[]='Le code URL ne peut pas être vide.';}if(in_array($type,['formations','metiers'],true)){if(!ctype_digit((string)$v['domain_id'])||!Catalog::find('domaines',(int)$v['domain_id']))$errors[]='Sélectionne un domaine existant.';else $v['domain_id']=(int)$v['domain_id'];}if($type==='etablissements'){if($v['email']!==''&&!filter_var($v['email'],FILTER_VALIDATE_EMAIL))$errors[]='Saisis une adresse e-mail valide.';if($v['website']!==''&&!filter_var($v['website'],FILTER_VALIDATE_URL))$errors[]='Saisis une URL valide.';}
 if($action==='update'&&(!$id||!Catalog::find($type,(int)$id)))$errors[]='L’entrée à modifier est introuvable.';if($errors){Session::flash('errors',$errors);Session::flash('values',$v);Response::redirect($base.($id?'?edit='.(int)$id:''));return;}$relations=match($type){'formations'=>['institution_ids'=>$r->body['institution_ids']??[],'career_ids'=>$r->body['career_ids']??[],'bac_series_ids'=>$r->body['bac_series_ids']??[]],'etablissements'=>['program_ids'=>$r->body['program_ids']??[]],'metiers'=>['program_ids'=>$r->body['program_ids']??[]],default=>[]};try{$recordId=$action==='update'?(int)$id:null;Catalog::save($type,$recordId,$v,$relations);$recordId??=(int)\App\Core\Database::connection()->lastInsertId();AuditLog::record((int)$actor['id'],$action==='create'?'catalog.created':'catalog.updated',$type,$recordId,['name'=>$v['name']??null],$r->server['REMOTE_ADDR']??null);Session::flash('success',$action==='create'?'Entrée créée.':'Modifications enregistrées.');}catch(PDOException $e){if($e->getCode()==='23000'){Session::flash('errors',['Un code similaire existe déjà ou une association est invalide.']);Session::flash('values',$v);Response::redirect($base.($id?'?edit='.(int)$id:''));return;}throw$e;}Response::redirect($base);}
 private function admin():bool{$u=Session::user();if(!$u){Response::redirect($this->path('/connexion'));return false;}if($u['role']!=='admin'){Response::text('Accès réservé à l’administration.',403);return false;}return true;}
 private function label(string $type):string{return['domaines'=>'Domaines','formations'=>'Formations','etablissements'=>'Établissements','metiers'=>'Métiers'][$type]??'Référentiel';}
 private function slug(string $s):string{$s=mb_strtolower(trim($s));$s=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$s)?:$s;return trim((string)preg_replace('/[^a-z0-9]+/','-', $s),'-');}
 private function path(string $p):string{$b=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'')),'/');return($b==='.'?'':$b).$p;}
}
